var l=[{title:`Τι κάνει τους μυς να αναπτύσσονται`,text:`Οι μύες αναπτύσσονται ως απόκριση στην επαναλαμβανόμενη μηχανική φόρτιση και στην επαρκή αποκατάσταση. Οι μεγάλες αλλαγές παίρνουν συνήθως μήνες ή χρόνια, όχι λίγες συνεδρίες ανύψωσης. Το να είστε δυνατοί και το να φαίνεστε πολύ μυώδεις είναι διαφορετικά αποτελέσματα, και μπορείτε να διαλέξετε προπονητικούς στόχους που ταιριάζουν σε αυτό που θέλετε.`},{title:`Τι δείχνουν οι συγκριτικές μελέτες`,text:`Μια μετα-ανάλυση του 2025 βρήκε ότι οι γυναίκες και οι άντρες απέκτησαν σε γενικές γραμμές παρόμοιο σχετικό μυϊκό μέγεθος με συγκρίσιμα προγράμματα προπόνησης με αντίσταση, αν και τα μέσα απόλυτα κέρδη των αντρών ήταν κάπως μεγαλύτερα. Αυτό δεν είναι λόγος να αποθαρρύνονται οι γυναίκες από την ανύψωση βαρών. Δείχνει ότι οι γυναίκες μπορούν να αποκτήσουν πραγματικό μυ και δύναμη.`},{title:`Προπονηθείτε για αυτό που θέλετε`,text:`Ορισμένοι άνθρωποι θέλουν ορατή μυϊκή ανάπτυξη. Άλλοι νοιάζονται περισσότερο για την καθημερινή δύναμη, την υγεία των οστών, την αθλητική απόδοση ή την αυτοπεποίθηση. Ο προπονητικός σας όγκος και η επιλογή ασκήσεων μπορούν να ακολουθούν αυτές τις προτεραιότητες. Η προπόνηση δύναμης δεν απαιτεί ρουτίνες bodybuilding ή βαρύτερα βάρη κάθε μέρα.`},{title:`Παράδειγμα`,text:`Δύο συνεδρίες ολόκληρου του σώματος την εβδομάδα με καθισιές, κωπηλασίες, πιέσεις και αρθρώσεις ισχίου μπορούν να βελτιώσουν τη δύναμη και τη λειτουργία. Παρακολουθείτε την απόδοσή σας, και μην ανησυχείτε ότι μία προπόνηση θα αλλάξει ξαφνικά την εμφάνισή σας.`},{title:`Χρήση του TrainUp`,text:`Στο Profile επιλέγετε τον στόχο σας: γενική φυσική κατάσταση, δύναμη ή φυσική κατάσταση αντοχής. Το πρόγραμμά σας χτίζεται από αυτόν τον στόχο, το επίπεδό σας, τον εξοπλισμό σας και τα σχόλιά σας για τις προπονήσεις, και δεν υπόσχεται κανένα συγκεκριμένο σχήμα σώματος.`}];var i=[{label:`Συστηματική ανασκόπηση του 2025: μυϊκή ανάπτυξη σε άντρες και γυναίκες`,url:`https://pubmed.ncbi.nlm.nih.gov/40028215/`},{label:`Θέση του ACSM για το 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:l,sources:i};export{n as default,l as sections,i as sources};